
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_revscanl_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_revscanl", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.885392040126328e+00, -4.786555800935257e+00, -4.648029164942637e+00, -4.456065958173433e+00, -4.194347411014212e+00, -3.845725674653452e+00, -3.396146590277508e+00, -2.836323470992379e+00, -2.194609746176277e+00, -1.510640604599951e+00, -8.488472563516380e-01, -6.416895375881502e-01, -6.645485997578300e-01, -5.320549700040512e-01, -3.596803716575829e-01, -1.910506837220420e-01, -7.403245756352149e-02, -2.047693045558608e-02, -2.907297457261647e-03, -1.387430303398378e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


